          "table surface",
          "desk surface",
          "console table surface",
          "coffee table surface",
          "side table surface"
        ],
        "required_properties": []
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "A device used to control the television or entertainment system.",
        "required_count": 1,
        "binding_policy": "SHARED",
