        "anchor_role": "piece_of_furniture"
      },
      {
        "id": "op_2",
        "operation": "Move entertainment control to an accessible location",
        "source_role": "entertainment_control",
        "target_role": "access_zone",
        "operation_count": 1,
        "reuse_policy": "DEDICATED_PER_TARGET",
